:root{--bg:#101418;--surface:#1c232b;--text:#eef3f7;--muted:#a4b0bc;--accent:#f59e0b;--accent-2:#fbbf24;--line:#2c3640;--max:1100px;--font:"Segoe UI",system-ui,sans-serif;--display:Impact,"Arial Black",sans-serif}
*{box-sizing:border-box}
body{margin:0;font-family:var(--font);color:var(--text);background:radial-gradient(ellipse at top,#1a222b 0%,var(--bg) 55%);line-height:1.6}
a{color:var(--accent-2);text-decoration:none}a:hover{color:var(--accent)}
.site-header{border-bottom:1px solid var(--line);background:rgba(16,20,24,.94);position:sticky;top:0;z-index:10}
.nav-inner{max-width:var(--max);margin:0 auto;padding:1rem 1.25rem;display:flex;align-items:center;justify-content:space-between;gap:1rem}
.brand{font-family:var(--display);letter-spacing:.03em;font-size:1.25rem;color:var(--text);font-weight:400}
.nav-links{display:flex;gap:1.2rem;flex-wrap:wrap}.nav-links a{color:var(--muted)}
.nav-links a:hover,.nav-links a[aria-current=page]{color:var(--accent)}
.hero{max-width:var(--max);margin:0 auto;padding:4rem 1.25rem 3rem}
.hero h1{font-family:var(--display);font-size:clamp(2.1rem,5vw,3.3rem);line-height:1.1;margin:0 0 1rem;letter-spacing:.02em}
.hero p{color:var(--muted);max-width:38rem;font-size:1.08rem}
.btn{display:inline-block;margin-top:1.4rem;padding:.75rem 1.2rem;background:var(--accent);color:#101418;border-radius:4px;font-weight:700}
.section{max-width:var(--max);margin:0 auto;padding:2rem 1.25rem 3rem}
.section h2{font-family:var(--display);font-size:1.7rem;letter-spacing:.03em}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1.2rem}
.card{background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:1.2rem}
.card h3{margin-top:0}.price{color:var(--accent-2);font-weight:700}
.menu-list{list-style:none;padding:0;margin:0}
.menu-list li{display:flex;justify-content:space-between;gap:1rem;padding:.85rem 0;border-bottom:1px solid var(--line)}
.site-footer{border-top:1px solid var(--line);margin-top:2rem;padding:2rem 1.25rem;color:var(--muted);text-align:center}
form{display:grid;gap:.85rem;max-width:28rem}
label{display:grid;gap:.35rem;color:var(--muted);font-size:.9rem}
input,textarea,select{padding:.7rem .8rem;border-radius:6px;border:1px solid var(--line);background:var(--surface);color:var(--text);font:inherit}
button[type=submit]{justify-self:start;padding:.75rem 1.2rem;border:0;border-radius:4px;background:var(--accent);color:#101418;font-weight:700;cursor:pointer}
@media (max-width:640px){.nav-inner{flex-direction:column;align-items:flex-start}}
